const SUPPORTED_LANGS = ['en','es','fr','pt'];
const LANG_NAMES = { en:'English', es:'Español', fr:'Français', pt:'Português' };

function getLang(){
  try {
    const stored = localStorage.getItem('together_lang');
    if (stored && SUPPORTED_LANGS.includes(stored)) return stored;
  } catch (e) {}
  const nav = (navigator.language || 'en').slice(0,2).toLowerCase();
  return SUPPORTED_LANGS.includes(nav) ? nav : 'en';
}

let currentLang = getLang();

function setLang(lang){
  if (!SUPPORTED_LANGS.includes(lang)) return;
  currentLang = lang;
  try { localStorage.setItem('together_lang', lang); } catch (e) {}
  document.documentElement.lang = lang;
  applyStaticTranslations();
  if (typeof onLangChange === 'function') onLangChange();
}

function t(key){
  return (TRANSLATIONS[currentLang] && TRANSLATIONS[currentLang][key])
    || TRANSLATIONS.en[key]
    || key;
}

function applyStaticTranslations(){
  document.querySelectorAll('[data-i18n]').forEach(el => {
    el.textContent = t(el.getAttribute('data-i18n'));
  });
  document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
    el.setAttribute('placeholder', t(el.getAttribute('data-i18n-placeholder')));
  });
}

function langSwitcherHTML(){
  return `<select id="langSwitcher" aria-label="Language" class="lang-switcher">` +
    SUPPORTED_LANGS.map(l => `<option value="${l}" ${l === currentLang ? 'selected' : ''}>${LANG_NAMES[l]}</option>`).join('') +
    `</select>`;
}

function wireLangSwitcher(){
  const sel = document.getElementById('langSwitcher');
  if (sel) sel.addEventListener('change', (e) => setLang(e.target.value));
}

document.documentElement.lang = currentLang;
